#include <bits/stdc++.h>
using namespace std;

typedef vector<pair<int,int>> Shape;

Shape normalize(Shape s) {
    int minr = INT_MAX, minc = INT_MAX;
    for (auto& p : s) { minr = min(minr, p.first); minc = min(minc, p.second); }
    for (auto& p : s) { p.first -= minr; p.second -= minc; }
    sort(s.begin(), s.end());
    return s;
}

Shape rotate(Shape s) {
    // 90 degrees clockwise: (r,c) -> (c, -r)
    Shape ns;
    for (auto& p : s) ns.push_back({p.second, -p.first});
    return normalize(ns);
}

set<Shape> allRotations(Shape s) {
    set<Shape> res;
    s = normalize(s);
    for (int i = 0; i < 4; i++) {
        res.insert(s);
        s = rotate(s);
    }
    return res;
}

