    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    vector<string> all;
    string s;
    while (getline(cin, s)) {
        if (!s.empty()) all.push_back(s);
    }

    int pos = 0;
    while (pos + 7 < (int)all.size()) {
        vector<string> g(8);
        for (int i = 0; i < 8; ++i) g[i] = all[pos + i];
        pos += 8;

        int minr = 8, maxr = -1, minc = 8, maxc = -1;
        for (int i = 0; i < 8; ++i) {
            for (int j = 0; j < 8; ++j) {
                if (g[i][j] == '1') {
                    minr = min(minr, i);
                    maxr = max(maxr, i);
                    minc = min(minc, j);
                    maxc = max(maxc, j);
                }
            }
        }

        vector<string> p;
        for (int i = minr; i <= maxr; ++i) {
            p.push_back(g[i].substr(minc, maxc - minc + 1));
        }

        int h = (int)p.size(), w = (int)p[0].size();
        vector<int> row(h, 0), col(w, 0);
        int ones = 0;
        for (int i = 0; i < h; ++i)
            for (int j = 0; j < w; ++j)
                if (p[i][j] == '1') {
                    row[i]++;
                    col[j]++;
                    ones++;
                }

        char ans = '?';

        if (h == 2 && w == 2 && ones == 4) ans = 'A';                 // square
        else if (h == 1 || w == 1) ans = 'B';                         // line
        else if (ones == h + w - 1) ans = 'C';                        // L
        else {
            bool fullTop = (row[0] == w);
            bool fullMid = false;
            for (int i = 1; i < h - 1; ++i) if (row[i] == w) fullMid = true;
            bool fullBottom = (row[h - 1] == w);

            bool fullLeft = (col[0] == h);
            bool fullMidCol = false;
            for (int j = 1; j < w - 1; ++j) if (col[j] == h) fullMidCol = true;
            bool fullRight = (col[w - 1] == h);

            if (fullTop && fullBottom && !fullMid && !fullLeft && !fullRight) {
                ans = 'D';                                            // C-like / U-like open side
            } else if (fullTop && fullMid && fullBottom) {
                ans = 'E';                                            // E-like
            } else if (fullTop && fullMid && !fullBottom) {
                ans = 'F';                                            // F-like
            } else {
                ans = 'G';                                            // remaining one
            }
        }

        cout << ans << "\n";
    }

    return 0;
}

