            minR = Math.min(minR, p[0]);
            minC = Math.min(minC, p[1]);
        }
        Set<String> pattern = new TreeSet<>();
        for (int[] p : cells) {
            pattern.add((p[0] - minR) + "," + (p[1] - minC));
        }
        System.out.println(identifyShape(pattern));
    }

    static String identifyShape(Set<String> pattern) {
        // Predefined normalized patterns for A to G
        Map<String, String> shapes = new HashMap<>();
        shapes.put("0,0 0,1 1,0 1,1", "A"); // 2x2 square
