        int minR = Integer.MAX_VALUE, minC = Integer.MAX_VALUE;
        for (int[] c : cells) { minR = Math.min(minR, c[0]); minC = Math.min(minC, c[1]); }
        List<int[]> res = new ArrayList<>();
        for (int[] c : cells) res.add(new int[]{c[0]-minR, c[1]-minC});
        res.sort((a,b) -> a[0]!=b[0] ? a[0]-b[0] : a[1]-b[1]);
        return res;
    }
    static List<int[]> rotate(List<int[]> cells) {
        List<int[]> res = new ArrayList<>();
        for (int[] c : cells) res.add(new int[]{c[1], -c[0]});
        return normalize(res);
    }
    static String key(List<int[]> cells) {
        StringBuilder sb = new StringBuilder();
        for (int[] c : cells) sb.append(c[0]).append(",").append(c[1]).append(";");
        return sb.toString();
    }
    static String canonical(List<int[]> cells) {
        String best = null;
        List<int[]> cur = normalize(cells);
        for (int i = 0; i < 4; i++) {
            String k = key(cur);
            if (best == null || k.compareTo(best) < 0) best = k;
            cur = rotate(cur);
        }
        return best;
    }
