import sys

def normalize(cells):
    """Translate cells so min row/col become 0, return sorted tuple."""
    min_r = min(r for r, c in cells)
    min_c = min(c for r, c in cells)
    return tuple(sorted((r - min_r, c - min_c) for r, c in cells))

def rotate90(cells):
    """Rotate around origin: (r, c) -> (c, -r)."""
    return [(c, -r) for r, c in cells]

def reflect(cells):
    """Reflect vertically: (r, c) -> (r, -c)."""
    return [(r, -c) for r, c in cells]

def all_transforms(cells):
    """All 8 symmetries, normalized."""
    res = set()
    cur = list(cells)
    for _ in range(4):
        res.add(normalize(cur))
        res.add(normalize(reflect(cur)))
        cur = rotate90(cur)
    return res

