int main() {
    char grid[8][9]; // 8 rows, each with 8 chars + null terminator
    char line[10];
    int dataset_count = 0;

    // Read all datasets
    while (1) {
        // Try to read first row of a dataset
        if (scanf("%8s", line) != 1) break;

        // If it's a blank line separator, skip
        if (line[0] == '\0') continue;

        // Store first row
        strcpy(grid[0], line);

        // Read remaining 7 rows
        for (int i = 1; i < 8; i++) {
            scanf("%8s", grid[i]);
        }

        // Find the shape by analyzing the pattern
        // We'll find the bounding box and count cells
        int min_r = 8, max_r = -1, min_c = 8, max_c = -1;
        int cell_count = 0;

        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                if (grid[r][c] == '1') {
                    cell_count++;
                    if (r < min_r) min_r = r;
                    if (r > max_r) max_r = r;
                    if (c < min_c) min_c = c;
                    if (c > max_c) max_c = c;
                }
            }
        }

        int height = max_r - min_r + 1;
        int width = max_c - min_c + 1;

        char shape;

        // Identify shape based on cell count and bounding box
        if (cell_count == 4) {
            if (height == 1 && width == 4) shape = 'A'; // horizontal line of 4
            else if (height == 4 && width == 1) shape = 'B'; // vertical line of 4
            else if (height == 2 && width == 2) shape = 'C'; // 2x2 square
            else if (height == 2 && width == 3) {
                // Check if it's L-shaped (D or E) or T-shaped (F)
                // Extract the 2x3 subgrid
                char sub[2][3];
                for (int r = 0; r < 2; r++) {
                    for (int c = 0; c < 3; c++) {
                        sub[r][c] = grid[min_r + r][min_c + c];
                    }
                }
                // D: L shape (3 in one row, 1 below at one end)
                // E: L shape (3 in one row, 1 below at other end)  
                // F: T shape (3 in top row, 1 in middle below)
                // G: Z shape (2, then 2 offset)

                int top_row = 0, bottom_row = 0;
                for (int c = 0; c < 3; c++) {
                    if (sub[0][c] == '1') top_row++;
                    if (sub[1][c] == '1') bottom_row++;
                }

                if (top_row == 3 && bottom_row == 1) {
                    // Find which column has the bottom cell
                    if (sub[1][0] == '1') shape = 'D';
                    else if (sub[1][2] == '1') shape = 'E';
                    else shape = 'F'; // middle column
                } else if (top_row == 1 && bottom_row == 3) {
                    // Rotated L or T
                    if (sub[0][0] == '1') shape = 'D'; // rotated
                    else if (sub[0][2] == '1') shape = 'E'; // rotated
                    else shape = 'F'; // rotated
                } else if (top_row == 2 && bottom_row == 2) {
                    shape = 'G'; // Z shape
                } else {
                    // Fallback: check actual pattern
                    shape = 'G'; // default
                }
            } else if (height == 3 && width == 2) {
                // Extract 3x2 subgrid
                char sub[3][2];
                for (int r = 0; r < 3; r++) {
                    for (int c = 0; c < 2; c++) {
                        sub[r][c] = grid[min_r + r][min_c + c];
                    }
                }
                // Check patterns
                int col0 = 0, col1 = 0;
                for (int r = 0; r < 3; r++) {
                    if (sub[r][0] == '1') col0++;
                    if (sub[r][1] == '1') col1++;
                }

                if (col0 == 3 && col1 == 1) {
                    if (sub[0][1] == '1') shape = 'D';
                    else if (sub[2][1] == '1') shape = 'E';
                    else shape = 'F';
                } else if (col0 == 1 && col1 == 3) {
                    if (sub[0][0] == '1') shape = 'D';
                    else if (sub[2][0] == '1') shape = 'E';
                    else shape = 'F';
                } else {
                    shape = 'G';
                }
            } else {
                shape = '?'; // shouldn't happen
            }
        } else {
            shape = '?'; // shouldn't happen
        }

        // More robust identification using pattern matching
        // Let's redo this properly by checking each shape template

        // Shape templates (all have exactly 4 cells)
        // A: horizontal line of 4
        // B: vertical line of 4  
        // C: 2x2 square
        // D: L shape (3 in row, 1 below at left)
        // E: L shape (3 in row, 1 below at right)
        // F: T shape (3 in top, 1 below middle)
        // G: Z shape (2, then 2 offset)

        // Let's use a more reliable method: compare with templates
        // First, normalize the shape to a minimal representation

        // Create a 8x8 pattern for the shape
        int pattern[8][8] = {0};
        for (int r = 0; r < 8; r++) {
            for (int c = 0; c < 8; c++) {
                pattern[r][c] = grid[r][c] - '0';
            }
        }

        // Try all 4 rotations of each shape template
        // Templates stored as lists of (r,c) offsets from top-left
        struct { int r, c; } templates[7][4] = {
            {{0,0},{0,1},{0,2},{0,3}}, // A: horizontal
            {{0,0},{1,0},{2,0},{3,0}}, // B: vertical
            {{0,0},{0,1},{1,0},{1,1}}, // C: square
            {{0,0},{0,1},{0,2},{1,0}}, // D: L left
            {{0,0},{0,1},{0,2},{1,2}}, // E: L right
            {{0,0},{0,1},{0,2},{1,1}}, // F: T
            {{0,0},{0,1},{1,1},{1,2}}  // G: Z
        };

        // For each shape, check if it matches (considering rotations)
        shape = '?';
        for (int s = 0; s < 7; s++) {
            // Try all 4 orientations (original + 3 rotations)
            // For each orientation, we need to check if the shape fits
            // Generate rotated versions of the template
            int found = 0;

            // Original orientation
            for (int rot = 0; rot < 4 && !found; rot++) {
                // Generate rotated offsets
                int roff[4], coff[4];
                for (int i = 0; i < 4; i++) {
                    int tr = templates[s][i].r;
                    int tc = templates[s][i].c;
                    switch (rot) {
                        case 0: roff[i] = tr; coff[i] = tc; break;
                        case 1: roff[i] = tc; coff[i] = 3 - tr; break; // 90 deg
                        case 2: roff[i] = 3 - tr; coff[i] = 3 - tc; break; // 180 deg
                        case 3: roff[i] = 3 - tc; coff[i] = tr; break; // 270 deg
                    }
                }

                // Find bounding box of rotated template
                int min_tr = 8, max_tr = -1, min_tc = 8, max_tc = -1;
                for (int i = 0; i < 4; i++) {
                    if (roff[i] < min_tr) min_tr = roff[i];
                    if (roff[i] > max_tr) max_tr = roff[i];
                    if (coff[i] < min_tc) min_tc = coff[i];
                    if (coff[i] > max_tc) max_tc = coff[i];
                }
                int tw = max_tc - min_tc + 1;
                int th = max_tr - min_tr + 1;

                // For each possible placement in the 8x8 grid
                for (int dr = 0; dr <= 8 - th && !found; dr++) {
                    for (int dc = 0; dc <= 8 - tw && !found; dc++) {
                        // Check if this placement matches the pattern
                        int match = 1;
                        // First check all template cells are 1 in pattern
                        for (int i = 0; i < 4 && match; i++) {
                            int pr = dr + (roff[i] - min_tr);
                            int pc = dc + (coff[i] - min_tc);
                            if (pr < 0 || pr >= 8 || pc < 0 || pc >= 8 || pattern[pr][pc] != 1) {
                                match = 0;
                            }
                        }
                        // Then check no extra 1s in the bounding box
                        if (match) {
                            for (int r = dr; r < dr + th && match; r++) {
                                for (int c = dc; c < dc + tw && match; c++) {
                                    int is_template = 0;
                                    for (int i = 0; i < 4; i++) {
                                        int pr = dr + (roff[i] - min_tr);
                                        int pc = dc + (coff[i] - min_tc);
                                        if (r == pr && c == pc) {
                                            is_template = 1;
                                            break;
                                        }
                                    }
                                    if (!is_template && pattern[r][c] == 1) {
                                        match = 0;
                                    }
                                }
                            }
                        }

                        if (match) {
                            found = 1;
                            shape = 'A' + s;
                        }
                    }
                }
            }

            if (found) break;
        }

        // Output the result
        printf("%c\n", shape);

        // Check for blank line separator or EOF
        // Try to read next character
        int ch = getchar();
        if (ch == EOF) break;
        // Skip blank lines
        while (ch == '\n') {
            ch = getchar();
            if (ch == EOF) break;
        }
        if (ch == EOF) break;
        // Put back the character we read
        ungetc(ch, stdin);
    }

    return 0;
}

#include <stdio.h>
