#include <stdlib.h>

typedef struct { int r, c; } Cell;

int cmp(const void *a, const void *b) {
    Cell *x = (Cell*)a, *y = (Cell*)b;
    if (x->r != y->r) return x->r - y->r;
    return x->c - y->c;
}

void normalize(Cell *cells, int n) {
    int minr = 100, minc = 100;
    for (int i = 0; i < n; i++) { if (cells[i].r < minr) minr = cells[i].r; if (cells[i].c < minc) minc = cells[i].c; }
    for (int i = 0; i < n; i++) { cells[i].r -= minr; cells[i].c -= minc; }
    qsort(cells, n, sizeof(Cell), cmp);
}

void rotate90(Cell *cells, int n) {
    for (int i = 0; i < n; i++) { int tmp = cells[i].r; cells[i].r = cells[i].c; cells[i].c = -tmp; }
    normalize(cells, n);
}

int equal(Cell *a, Cell *b, int n) {
    for (int i = 0; i < n; i++) if (a[i].r != b[i].r || a[i].c != b[i].c) return 0;
    return 1;
}

