int main(void) {
    char line[128];
    char grid[8][16];
    int row = 0;

    while (fgets(line, sizeof(line), stdin)) {
        int len = (int)strlen(line);
        while (len > 0 && (line[len - 1] == '\n' || line[len - 1] == '\r')) {
            line[--len] = '\0';
        }

        if (len == 0) continue; /* skip blank lines */

        strcpy(grid[row++], line);

        if (row == 8) {
            int minr = 8, maxr = -1, minc = 8, maxc = -1;
            int r, c;

            for (r = 0; r < 8; r++) {
                for (c = 0; c < 8; c++) {
                    if (grid[r][c] == '1') {
                        if (r < minr) minr = r;
                        if (r > maxr) maxr = r;
                        if (c < minc) minc = c;
                        if (c > maxc) maxc = c;
                    }
                }
            }

            int h = maxr - minr + 1;
            int w = maxc - minc + 1;
            char pat[8][8];
            int ones = 0;

            for (r = 0; r < h; r++) {
                for (c = 0; c < w; c++) {
                    pat[r][c] = grid[minr + r][minc + c];
                    if (pat[r][c] == '1') ones++;
                }
                pat[r][w] = '\0';
            }

            char ans = '?';

            if (h == 2 && w == 2 && ones == 4) {
                ans = 'A'; /* square */
            } else if (h == 1 && w == 4 && ones == 4) {
                ans = 'B'; /* horizontal line */
            } else if (h == 4 && w == 1 && ones == 4) {
                ans = 'C'; /* vertical line */
            } else if (h == 2 && w == 3 && ones == 4) {
                /* S or Z */
                if (strcmp(pat[0], "011") == 0 && strcmp(pat[1], "110") == 0)
                    ans = 'D';
                else if (strcmp(pat[0], "110") == 0 && strcmp(pat[1], "011") == 0)
                    ans = 'E';
            } else if (h == 3 && w == 2 && ones == 4) {
                /* L or mirrored L */
                if (strcmp(pat[0], "10") == 0 &&
                    strcmp(pat[1], "10") == 0 &&
                    strcmp(pat[2], "11") == 0)
                    ans = 'F';
                else if (strcmp(pat[0], "01") == 0 &&
                         strcmp(pat[1], "01") == 0 &&
                         strcmp(pat[2], "11") == 0)
                    ans = 'G';
            }

            if (ans != '?') {
                putchar(ans);
                putchar('\n');
            }

            row = 0;
        }
    }

    return 0;
}
